import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CYjxsSA2.js";const b=JSON.parse('{"title":"下载与安装","description":"","frontmatter":{},"headers":[],"relativePath":"download.md","filePath":"download.md"}'),o={name:"download.md"};function s(n,t,l,i,h,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h1><p>本章说明如何部署运行 VAELOR，以及首次运行可能涉及的可选资源。</p><p>当前版本：<strong>DXE-1.0.0</strong>。</p><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to &quot;运行环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>依赖</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Windows</td><td>10 / 11</td><td>系统自带所需运行时，无需额外安装</td></tr><tr><td>macOS</td><td>12+（Apple Silicon）</td><td>发行包为 <code>.app</code>，自签名</td></tr><tr><td>Docker Desktop</td><td>可选</td><td>军团的内网攻击能力依赖 Kali 容器，见 <a href="/vaelor/advanced/docker.html">Kali 工具箱</a></td></tr></tbody></table><p>VAELOR <strong>开箱即用</strong>：发行包解开即可运行，<strong>不需要账号、不需要授权文件、不需要联网激活</strong>。</p><h2 id="获取程序" tabindex="-1">获取程序 <a class="header-anchor" href="#获取程序" aria-label="Permalink to &quot;获取程序&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发行包/</span></span>
<span class="line"><span>├── VAELOR(.exe)   ← 主程序</span></span>
<span class="line"><span>└── browser/       ← 可选：随包 Headless Chrome 运行时</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">可执行文件名</p><p>对外产品名是 <strong>VAELOR</strong>；可执行文件名与数据目录名沿用 <code>ErraticGopher</code>，改名会牵动已有用户的数据迁移，故本期未跟随。</p></div><h2 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h2><p>所有数据都保存在本机的<strong>数据目录</strong>里，与安装目录分开：</p><table tabindex="0"><thead><tr><th>平台</th><th>位置</th></tr></thead><tbody><tr><td>Windows</td><td>程序所在目录</td></tr><tr><td>macOS</td><td>系统的应用数据目录（不在应用包内）</td></tr></tbody></table><p>数据目录里包含项目数据、导出结果、作业工作区、技能与浏览器运行时、抓包根证书。需要迁移或备份时，把整份目录拷走即可；也可以把它放到其他位置。</p><div class="tip custom-block"><p class="custom-block-title">找不到数据</p><p>扫描 / 项目数据在<strong>数据目录</strong>，不在安装目录。</p></div><h2 id="可选资源" tabindex="-1">可选资源 <a class="header-anchor" href="#可选资源" aria-label="Permalink to &quot;可选资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>说明</th></tr></thead><tbody><tr><td><strong>Docker Desktop</strong></td><td>军团的内网攻击功能依赖 Kali 容器，详见 <a href="/vaelor/advanced/docker.html">Kali 工具箱</a></td></tr><tr><td><strong>WSL</strong></td><td>无法安装 Docker 的 Windows 环境，可用 WSL 工具箱作为隔离环境</td></tr><tr><td><strong>IP 归属离线库</strong></td><td>缺失时归属列显示「未知」，不影响其他功能</td></tr><tr><td><strong>随包浏览器</strong></td><td>未随包时使用系统 Chrome / Chromium，见 <a href="/vaelor/advanced/browser.html">无头浏览器与取证</a></td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/vaelor/quickstart.html">快速上手</a> — 创建第一个项目</li><li><a href="/vaelor/advanced/settings.html">系统配置</a> — 配好大模型 Provider</li></ul>`,18)])])}const m=a(o,[["render",s]]);export{b as __pageData,m as default};
